<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { api } from '../api/client'
import type { Report } from '../api/types'
import { useAuthStore } from '../stores/auth'
const id=Number(useRoute().params.id); const auth=useAuthStore(); const report=ref<Report>(); const history=ref<Report[]>([]); const week=ref(''); const note=ref('')
const content=computed(()=>report.value?.content||{})
async function load(){try{report.value=await api<Report>('GET',`/projects/${id}/reports`,undefined,week.value?{week:week.value}:undefined);note.value=report.value.note||'';history.value=await api('GET',`/projects/${id}/reports/history`)}catch(e){ElMessage.error((e as Error).message)}}
async function ensureDraft():Promise<Report>{const current=report.value;if(current?.id)return current; const start=current?.weekStart;if(!start)throw new Error('缺少周起始日');const created=await api<Report>('POST',`/projects/${id}/reports`,{weekStart:start});report.value=created;return created}
async function save(){try{const item=await ensureDraft();report.value=await api('PUT',`/reports/${item.id}/note`,{note:note.value});ElMessage.success('说明已保存')}catch(e){ElMessage.error((e as Error).message)}}
async function publish(){try{const item=await ensureDraft();report.value=await api('POST',`/reports/${item.id}/publish`);await load();ElMessage.success('周报已发布')}catch(e){ElMessage.error((e as Error).message)}} onMounted(load)
</script>
<template><div><header class="page-head"><div><h1>项目周报</h1><p>{{report?.weekStart}} 至 {{report?.weekEnd}} · {{report?.status==='PUBLISHED'?'已发布':'实时草稿'}}</p></div><el-date-picker v-model="week" value-format="YYYY-MM-DD" placeholder="选择周" @change="load"/></header><div class="grid" style="grid-template-columns:minmax(0,1fr) 300px"><main class="grid"><section class="surface"><h2>工时概览</h2><div class="metric-row"><span class="metric"><strong>{{content.actualDays??0}}</strong>本周实际人天</span><span class="metric"><strong>{{content.plannedDays??0}}</strong>本周计划人天</span><span class="metric"><strong>{{content.completedNodes?.length??0}}</strong>完成节点</span><span class="metric"><strong class="danger">{{content.exceptionNodes?.length??0}}</strong>异常节点</span></div></section><section class="surface"><h2>本周完成</h2><el-table :data="content.completedNodes||[]"><el-table-column prop="name" label="节点"/><el-table-column prop="actualEnd" label="完成日期"/></el-table></section><section class="surface"><h2>延期与受阻</h2><el-table :data="content.exceptionNodes||[]"><el-table-column prop="name" label="节点"/><el-table-column prop="planEnd" label="计划完成"/><el-table-column prop="overdueReason" label="延期原因"/></el-table></section><section class="surface"><h2>风险与说明</h2><el-input v-model="note" type="textarea" :rows="5" :disabled="report?.status==='PUBLISHED'||auth.isViewer"/><div v-if="report?.status!=='PUBLISHED'&&!auth.isViewer" class="form-actions"><el-button @click="save">保存说明</el-button><el-button type="primary" @click="publish">发布周报</el-button></div></section></main><aside class="surface"><h2>历史周报</h2><div v-for="item in history" :key="item.id" style="padding:12px 0;border-bottom:1px solid var(--line)"><strong>{{item.weekStart}}</strong><small class="muted" style="display:block">{{item.status}}</small></div><div v-if="!history.length" class="empty">暂无历史</div></aside></div></div></template>
